function uid(){return'CYL-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6).toUpperCase()}state.cylinders.forEach(c=>c.uid||(c.uid=uid()));const migrateRefs=a=>(a||[]).map(v=>state.cylinders.some(c=>c.uid===v)?v:(state.cylinders.find(c=>c.id===v)?.uid||v));state.batches.forEach(b=>{b.cylinders=migrateRefs(b.cylinders);b.defects=migrateRefs(b.defects)});state.issues.forEach(i=>{i.cylinders=migrateRefs(i.cylinders);i.cancelled??=false});
const nav=[['dashboard','▦','Главная'],['cylinders','◉','Данные о баллонах'],['batches','▣','Создание партии'],['issue','↗','Выдача баллонов'],['return','↙','Возврат баллонов'],['receive','↓','Приём баллонов']];let route='dashboard';const $=s=>document.querySelector(s),view=$('#view'),today=()=>new Date().toISOString().slice(0,10);const save=note=>{if(!cloudMode)localStorage.setItem('balloon-registry-v1',JSON.stringify(state));window.dispatchEvent(new CustomEvent('balloon:save',{detail:{note:note||window.BALLOON_AUDIT_NOTE||'Обновление реестра'}}));window.BALLOON_AUDIT_NOTE=''};const date=d=>{if(!d)return'—';let parsed=new Date(d+'T12:00:00');return Number.isNaN(parsed.getTime())?escapeHTML(d):new Intl.DateTimeFormat('ru-RU').format(parsed)};const cyl=u=>state.cylinders.find(c=>c.uid===u);const usable=()=>state.cylinders.filter(c=>['На складе','Возвращён'].includes(c.status));
function plus18(d){if(!d)return'';let x=new Date(d+'T12:00:00');x.setMonth(x.getMonth()+18);return x.toISOString().slice(0,10)}function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)}function status(s){return`<span class="status ${s==='Выдан'?'issued':(['Освидетельствование','Брак'].includes(s)?'service':'')}">${s}</span>`}const head=(t,d,a='')=>`<div class="page-head"><div><h1>${t}</h1><p>${d}</p></div>${a}</div>`;
function renderNav(){$('#nav').innerHTML=nav.map(n=>`<button class="nav-item ${route===n[0]?'active':''}" data-route="${n[0]}"><span class="nav-icon">${n[1]}</span>${n[2]}</button>`).join('');$('#breadcrumbs').textContent=nav.find(n=>n[0]===route)?.[2]||'';bindRoutes()}function bindRoutes(){document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route))}function go(r){route=r;renderNav();render();$('.sidebar').classList.remove('open')}
