function cylinders(){view.innerHTML=head('Данные о баллонах','Заводской номер может повторяться: учёт ведётся по внутреннему ID.',`<button class="button" id="addCylinder">+ Добавить баллон</button>`)+`<div class="toolbar"><input id="search" class="search" placeholder="Поиск по номеру, ID, держателю…"></div><div class="card table-wrap"><table class="table"><thead><tr><th>Внутренний ID</th><th>Номер баллона</th><th>Объём</th><th>Держатель</th><th>Статус</th><th></th></tr></thead><tbody id="cylinderRows"></tbody></table></div>`;let draw=()=>{let q=$('#search').value.toLowerCase();$('#cylinderRows').innerHTML=state.cylinders.filter(c=>[c.uid,c.id,c.status,c.holder,c.manufacturer].join(' ').toLowerCase().includes(q)).map(c=>`<tr class="clickable" data-cylinder="${c.uid}"><td class="mono">${c.uid}</td><td class="mono"><strong>${c.id}</strong></td><td>${c.volume} л</td><td>${c.holder||'—'}</td><td>${status(c.status)}</td><td>›</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Ничего не найдено</td></tr>';document.querySelectorAll('[data-cylinder]').forEach(e=>e.onclick=()=>cylinderModal(e.dataset.cylinder))};$('#search').oninput=draw;draw();$('#addCylinder').onclick=cylinderForm}
