function cylinderForm(){open(`<h2>Новый баллон</h2><p>Поля со звёздочкой обязательны. Производитель и держатель — желательны.</p><form id="cylinderForm" class="form-grid"><label class="field">Номер баллона *<input required name="id"></label><label class="field">Объём, л *<input required name="volume" type="number" value="40"></label><label class="field">Дата производства *<input required name="made" type="date"></label><label class="field">Дата освидетельствования *<input required name="inspection" type="date"></label><label class="field">Производитель<input name="manufacturer"></label><label class="field">Держатель<input name="holder"></label><div class="form-actions full"><button type="button" class="button secondary" data-close>Отмена</button><button class="button">Добавить</button></div></form>`);$('#cylinderForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.uid=uid();x.status='На складе';x.history=[[today(),'Приём','Добавлен в реестр']];state.cylinders.push(x);save();close();cylinders();toast(`Баллон добавлен: ${x.uid}`)}}
