function issuanceForm(){let a=usable();view.innerHTML=head('Выдача баллонов','Выберите серию и баллоны из списка либо укажите номера вручную.')+`<form id="issueForm" class="card form-card"><h2>Протокол поставки</h2><div class="form-grid three"><label class="field">Серия КГМ *<select required name="batch" id="issueBatch"><option value="">Выберите серию</option>${state.batches.map(b=>`<option value="${b.number}">${b.number} · до ${date(b.expiry)}</option>`).join('')}</select></label><label class="field">Дата производства *<input required name="production" id="issueProduction" type="date"></label><label class="field">Дата окончания срока<input id="expiry" readonly></label><label class="field">Дата разрешения *<input required name="permission"></label><label class="field">Дата выдачи *<input required name="date" type="date" value="${today()}"></label><label class="field">Номер накладной *<input required name="invoice"></label><label class="field full">Организация *<input required name="org"></label><label class="field">Выдал сотрудник *<input required name="employee" value="${escapeHTML(window.BALLOON_DISPLAY_NAME||String())}"></label><label class="field full">Номера вручную<textarea id="issueManual" placeholder="Номер или ID, по одному в строке"></textarea></label></div><div class="scan-line">Доступные баллоны — отметьте нужные</div><div class="chips">${a.map(c=>`<label class="chip"><input type="checkbox" name="cylinder" value="${c.uid}"> ${c.id} · ${c.volume} л <small>${c.uid}</small></label>`).join('')||'Нет баллонов для выдачи'}</div><div class="form-actions"><button type="button" class="button secondary" id="previewProtocol">Предпросмотр</button><button class="button">Оформить выдачу</button></div></form><div class="card panel" style="margin-top:20px"><div class="panel-head"><h2>История выдач</h2><small>Удаление недоступно: запись можно только аннулировать.</small></div><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Организация</th><th>Накладная</th><th>Серия</th><th>Статус</th><th></th></tr></thead><tbody>${state.issues.map((i,n)=>`<tr><td>${date(i.date)}</td><td>${i.org}</td><td>№${i.invoice}</td><td>${i.batch}</td><td>${status(i.cancelled?'Аннулирован':'Действует')}</td><td><button class="button secondary small" data-edit-issue="${n}">Изменить</button>${i.cancelled?'':` <button class="button danger small" data-cancel-issue="${n}">Аннулировать</button>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Выдач пока нет</td></tr>'}</tbody></table></div></div>`;$('#issueBatch').onchange=syncBatch;$('#issueProduction').oninput=e=>$('#expiry').value=plus18(e.target.value);$('#issueForm').onsubmit=e=>finishIssue(e,false);$('#previewProtocol').onclick=()=>finishIssue(null,true);document.querySelectorAll('[data-cancel-issue]').forEach(b=>b.onclick=()=>cancelIssue(+b.dataset.cancelIssue));document.querySelectorAll('[data-edit-issue]').forEach(b=>b.onclick=()=>editIssue(+b.dataset.editIssue))}
function syncBatch(){let b=state.batches.find(b=>b.number===$('#issueBatch').value);if(!b)return;$('#issueProduction').value=b.produced;$('#expiry').value=b.expiry;let us=new Set(b.cylinders);$('#issueForm').querySelectorAll('input[name=cylinder]').forEach(x=>x.checked=us.has(x.value))}function issueData(){let f=$('#issueForm');if(!f.reportValidity())return null;let fd=new FormData(f),x=Object.fromEntries(fd),m=resolve($('#issueManual').value);x.cylinders=[...new Set([...fd.getAll('cylinder'),...m.found])];if(m.miss.length){toast(`Не найдены или недоступны: ${m.miss.join(', ')}`);return null}if(!x.cylinders.length){toast('Выберите или укажите баллоны');return null}x.expiry=$('#expiry').value;return x}async function finishIssue(e,preview){if(e)e.preventDefault();let x=issueData();if(!x)return;if(preview){protocol(x);return}const submitButton=e?.submitter;if(submitButton)submitButton.disabled=true;x.cancelled=false;x.verificationToken=crypto.randomUUID();state.issues.unshift(x);x.cylinders.forEach(u=>{let c=cyl(u);c.status='Выдан';c.history.unshift([x.date,'Выдача',`Выдан ${x.org}, накладная №${x.invoice}, серия ${x.batch}`])});save();try{if(cloudMode)await window.BALLOON_CLOUD_SYNC.whenSaved();issuanceForm();toast('Выдача оформлена');protocol(x)}catch(error){toast('Выдача не сохранена: '+error.message)}}
function editIssue(n){let x=state.issues[n];open(`<h2>Изменить выдачу</h2><p>Запись останется в истории. Состав баллонов изменяется только через аннулирование и новую выдачу.</p><form id="editIssue" class="form-grid"><label class="field">Организация<input name="org" required value="${x.org}"></label><label class="field">Накладная<input name="invoice" required value="${x.invoice}"></label><label class="field">Дата выдачи<input name="date" required type="date" value="${x.date}"></label><label class="field">Выдал<input name="employee" required value="${x.employee}"></label><div class="form-actions full"><button type="button" class="button secondary" data-close>Отмена</button><button class="button">Сохранить</button></div></form>`);$('#editIssue').onsubmit=e=>{e.preventDefault();Object.assign(x,Object.fromEntries(new FormData(e.target)));save();close();issuanceForm();toast('Выдача исправлена')}}function cancelIssue(n){let x=state.issues[n];x.cancelled=true;x.cylinders.forEach(u=>{let c=cyl(u);if(c?.status==='Выдан'){c.status='На складе';c.history.unshift([today(),'Аннулирование',`Выдача по накладной №${x.invoice} аннулирована`])}});save();issuanceForm();toast('Выдача аннулирована и исключена из остатка')}
function protocol(x){let rows=x.cylinders.map((u,i)=>{let c=cyl(u);return`<tr><td>${i+1}</td><td>${c?.id||u}</td><td>${c?.volume||'—'} л</td></tr>`}).join('');open(`<div id="protocolDocument"><h2>Протокол поставки №${x.invoice}</h2><p>${x.org} · ${date(x.date)}</p><div class="detail-grid"><div class="detail"><span>Серия</span><strong>${x.batch}</strong></div><div class="detail"><span>Производство</span><strong>${date(x.production)}</strong></div><div class="detail"><span>Срок годности</span><strong>${date(x.expiry)}</strong></div><div class="detail"><span>Разрешение</span><strong>${x.permission}</strong></div></div><table class="table"><thead><tr><th>№</th><th>Баллон</th><th>Объём</th></tr></thead><tbody>${rows}</tbody></table><p>Выдал: <strong>${x.employee}</strong></p></div><div class="form-actions"><button class="button secondary" data-close>Закрыть</button><button class="button secondary" id="wordProtocol">Word</button><button class="button" id="printProtocol">Печать / PDF</button></div>`);$('#printProtocol').onclick=()=>window.print();$('#wordProtocol').onclick=()=>downloadWord(x.invoice)}function downloadWord(n){let h=`<html><meta charset="utf-8"><body>${$('#protocolDocument').innerHTML}</body></html>`,b=new Blob(['\ufeff',h],{type:'application/msword'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`Протокол_${n}.doc`;a.click();URL.revokeObjectURL(a.href)}
function returns(){let issued=state.cylinders.filter(c=>c.status==='Выдан');view.innerHTML=head('Возврат баллонов','Введите номер вручную или выберите баллоны. Система покажет серию исходной выдачи.')+`<div class="card form-card"><h2>Принять возврат</h2><label class="field">Номера или внутренние ID вручную<textarea id="returnManual" placeholder="По одному номеру или ID в строке"></textarea></label><div class="scan-line">Баллоны у организаций</div><div class="table-wrap"><table class="table"><thead><tr><th></th><th>Баллон</th><th>Серия и выдача</th><th>Статус</th></tr></thead><tbody>${issued.map(c=>{let i=state.issues.find(i=>!i.cancelled&&i.cylinders.includes(c.uid));return`<tr><td><input type="checkbox" value="${c.uid}"></td><td class="mono"><strong>${c.id}</strong><small> ${c.uid}</small></td><td>${i?`${i.batch} · ${date(i.date)} · ${i.org}`:'Выдача не найдена'}</td><td>${status(c.status)}</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Нет выданных баллонов</td></tr>'}</tbody></table></div><div class="form-actions"><button class="button" id="returnSelected">Принять возврат</button></div></div>`;$('#returnSelected').onclick=()=>{let checked=[...view.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value),m=resolve($('#returnManual').value,issued),ids=[...new Set([...checked,...m.found])];if(m.miss.length){toast(`Не найдены среди выданных: ${m.miss.join(', ')}`);return}if(!ids.length){toast('Укажите или выберите баллоны');return}ids.forEach(u=>{let c=cyl(u),i=state.issues.find(i=>!i.cancelled&&i.cylinders.includes(u));c.status='Возвращён';c.history.unshift([today(),'Возврат',`Возвращён на склад${i?`; серия ${i.batch}, накладная №${i.invoice}`:''}`])});save();returns();toast('Возврат принят; статус изменён на «Возвращён»')}}
function receive(){view.innerHTML=head('Приём баллонов','Добавьте новые или б/у баллоны, ранее не стоявшие на балансе')+`<form id="receiveForm" class="card form-card"><h2>Приём на баланс</h2><div class="form-grid"><label class="field">Номер баллона *<input required name="id"></label><label class="field">Состояние<select name="condition"><option>Новый</option><option>Б/у</option></select></label><label class="field">Объём, л *<input required name="volume" type="number" value="40"></label><label class="field">Дата производства *<input required name="made" type="date"></label><label class="field">Дата освидетельствования *<input required name="inspection" type="date"></label><label class="field">Источник / поставщик<input name="source"></label><label class="field full">Примечание<textarea name="note"></textarea></label></div><div class="form-actions"><button class="button">Принять на баланс</button></div></form>`;$('#receiveForm').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.uid=uid();x.status='На складе';x.history=[[today(),'Приём',`${x.condition}; ${x.source||'источник не указан'}`]];state.cylinders.push(x);save();e.target.reset();toast(`Баллон принят: ${x.uid}`)}}
