function addBatchPermissionField(){let form=$('#batchForm');if(!form)return;let number=form.querySelector('[name=number]')?.value,old=state.batches.find(b=>b.number===number),grid=form.querySelector('.form-grid');if(!form.querySelector('[name=permissionDate]'))grid.insertAdjacentHTML('beforeend',`<label class="field">Дата выдачи разрешения *<input required name="permissionDate" type="date" value="${old?.permissionDate||''}"></label>`);if(!form.querySelector('[name=volume]'))grid.insertAdjacentHTML('beforeend',`<label class="field">Объём баллонов *<select required name="volume"><option value="">Выберите объём</option><option value="2" ${old?.volume==='2'?'selected':''}>2 литра</option><option value="10" ${old?.volume==='10'?'selected':''}>10 литров</option><option value="40" ${old?.volume==='40'?'selected':''}>40 литров</option></select></label>`);if(!form.querySelector('[data-doc="certificate"]'))grid.insertAdjacentHTML('beforeend',`<label class="field">Сертификат качества <input data-doc="certificate" type="file" accept=".pdf,.doc,.docx,image/*"><small>Необязательно, но желательно</small></label><label class="field">Разрешение <input data-doc="permit" type="file" accept=".pdf,.doc,.docx,image/*"><small>Необязательно, но желательно</small></label>`)}
document.addEventListener('submit',e=>{
  if(e.target?.id!=='batchForm')return;
  const form=e.target,number=form.querySelector('[name=number]')?.value;
  const files=[['certificate',form.querySelector('[data-doc="certificate"]')?.files?.[0]],['permit',form.querySelector('[data-doc="permit"]')?.files?.[0]]].filter(([,file])=>file);
  if(!files.length)return;
  setTimeout(async()=>{
    if(!$('#modal').classList.contains('hidden'))return;
    const batch=state.batches.find(item=>item.number===number);
    if(!batch)return;
    if(!cloudMode){toast('Документы загружаются только в облачной версии');return}
    for(const [kind,file] of files){
      try{
        const path=await window.BALLOON_DOCUMENTS_API.upload(file,kind);
        if(kind==='certificate'){batch.certificateName=file.name;batch.certificatePath=path}
        else{batch.permitDocumentName=file.name;batch.permitDocumentPath=path}
        save(`Документ партии ${batch.number}: ${kind==='certificate'?'сертификат качества':'разрешение'}`);
        toast(`Документ загружен: ${file.name}`);
      }catch(error){toast(`Документ не загружен: ${error.message}`)}
    }
  },0);
},true);
function batchesData(){view.innerHTML=head('Данные о партиях','Реестр загруженных серий, их реквизиты и документы.')+`<div class="card table-wrap"><table class="table"><thead><tr><th>Серия</th><th>Дата наполнения</th><th>Срок годности</th><th>Объём</th><th>Наполнял</th><th>Баллонов</th><th>Документы</th></tr></thead><tbody>${state.batches.map(b=>`<tr><td class="mono"><strong>${b.number}</strong></td><td>${date(b.produced)}</td><td>${date(b.expiry)}</td><td>${b.volume?b.volume+' л':'—'}</td><td>${b.filler||'—'}</td><td>${b.cylinders.length}</td><td>${b.certificateName?`Сертификат: ${b.certificateName}<br>`:'Сертификат не загружен<br>'}${b.permitDocumentName?`Разрешение: ${b.permitDocumentName}`:'Разрешение не загружено'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Загруженных серий пока нет</td></tr>'}</tbody></table></div>`}
