function batchesData(){view.innerHTML=head('Данные о партиях','Реестр загруженных серий, их реквизиты и документы.')+`<div class="card table-wrap"><table class="table"><thead><tr><th>Серия</th><th>Дата наполнения</th><th>Срок годности</th><th>Объём</th><th>Наполнял</th><th>Баллонов</th><th>Документы</th><th></th></tr></thead><tbody>${state.batches.map((b,i)=>`<tr><td class="mono"><strong>${b.number}</strong></td><td>${date(b.produced)}</td><td>${date(b.expiry)}</td><td>${b.volume?b.volume+' л':'—'}</td><td>${b.filler||'—'}</td><td>${b.cylinders.length}</td><td>${b.certificateName?'Сертификат загружен':'Сертификат не загружен'}<br>${b.permitDocumentName?'Разрешение загружено':'Разрешение не загружено'}</td><td><button class="button secondary small" data-batch-detail="${i}">Подробнее</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Загруженных серий пока нет</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-batch-detail]').forEach(b=>b.onclick=()=>batchDetail(+b.dataset.batchDetail))}
function batchDetail(index){let b=state.batches[index],items=b.cylinders.map(u=>cyl(u)).filter(Boolean),defects=(b.defects||[]).map(u=>cyl(u)).filter(Boolean);open(`<h2>Серия ${b.number}</h2><p>Детальная информация о наполнении и составе партии.</p><div class="detail-grid"><div class="detail"><span>Дата наполнения</span><strong>${date(b.produced)}</strong></div><div class="detail"><span>Срок годности</span><strong>${date(b.expiry)}</strong></div><div class="detail"><span>Объём серии</span><strong>${b.volume?b.volume+' л':'Не указан'}</strong></div><div class="detail"><span>Наполнял</span><strong>${b.filler||'—'}</strong></div><div class="detail"><span>Дата разрешения</span><strong>${date(b.permissionDate)}</strong></div><div class="detail"><span>Баллонов</span><strong>${items.length}</strong></div></div><div class="scan-line">Сертификат качества: ${b.certificateName||'не загружен'}<br>Разрешение: ${b.permitDocumentName||'не загружено'}</div><h3>Баллоны в партии</h3><div class="table-wrap"><table class="table"><thead><tr><th>Номер</th><th>Внутренний ID</th><th>Объём</th><th>Статус</th><th>Производство</th><th>Освидетельствование</th></tr></thead><tbody>${items.map(c=>`<tr><td class="mono"><strong>${c.id}</strong></td><td class="mono">${c.uid}</td><td>${c.volume||b.volume||'—'} л</td><td>${status(c.status)}</td><td>${date(c.made)}</td><td>${date(c.inspection)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">В серии пока нет баллонов</td></tr>'}</tbody></table></div>${defects.length?`<h3>Бракованные баллоны</h3><p>${defects.map(c=>`${c.id} (${c.volume||b.volume||'—'} л)`).join(', ')}</p>`:''}<div class="form-actions"><button class="button secondary" data-close>Закрыть</button></div>`)}

state.organizations??=[{name:'ООО «Север»',inn:'',contact:''}];
if(!nav.some(n=>n[0]==='organizations'))nav.push(['organizations','▦','Организации']);
function organizations(){view.innerHTML=head('Организации','Справочник покупателей кислорода.',`<button class="button" id="addOrganization">+ Добавить организацию</button>`)+`<div class="card table-wrap"><table class="table"><thead><tr><th>Наименование</th><th>ИНН</th><th>Контакт</th></tr></thead><tbody>${state.organizations.map(o=>`<tr><td><strong>${o.name}</strong></td><td>${o.inn||'—'}</td><td>${o.contact||'—'}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Организаций пока нет</td></tr>'}</tbody></table></div>`;$('#addOrganization').onclick=organizationForm}
function organizationForm(){open(`<h2>Новая организация</h2><p>Запись появится в списке при оформлении выдачи.</p><form id="organizationForm" class="form-grid"><label class="field full">Наименование *<input required name="name"></label><label class="field">ИНН<input name="inn"></label><label class="field">Контактное лицо / телефон<input name="contact"></label><div class="form-actions full"><button type="button" class="button secondary" data-close>Отмена</button><button class="button">Добавить</button></div></form>`);$('#organizationForm').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));if(state.organizations.some(x=>x.name.toLowerCase()===o.name.toLowerCase())){toast('Такая организация уже есть');return}state.organizations.push(o);save();close();organizations();toast('Организация добавлена')}}

function issuanceForm(){view.innerHTML=head('Выдача баллонов','Выберите серию, затем отметьте баллоны этой серии или введите их номера вручную.')+`<form id="issueForm" class="card form-card"><h2>Протокол поставки</h2><div class="form-grid three"><label class="field">Серия КГМ *<select required name="batch" id="issueBatch"><option value="">Выберите серию</option>${state.batches.map(b=>`<option value="${b.number}">${b.number} · ${b.volume||'объём не указан'} л</option>`).join('')}</select></label><label class="field">Дата производства *<input required name="production" id="issueProduction" type="date"></label><label class="field">Дата окончания срока<input id="expiry" readonly></label><label class="field">Дата разрешения *<input required name="permission" id="issuePermission" type="date"></label><label class="field">Дата выдачи *<input required name="date" type="date" value="${today()}"></label><label class="field">Номер накладной *<input required name="invoice"></label><label class="field full">Организация из списка<select id="organizationSelect"><option value="">Ввести вручную</option>${state.organizations.map(o=>`<option value="${o.name}">${o.name}</option>`).join('')}</select></label><label class="field full">Организация *<input required name="org" id="organizationInput" placeholder="Можно ввести вручную"></label><label class="field">Выдал сотрудник *<input required name="employee" value="${escapeHTML(window.BALLOON_DISPLAY_NAME||String())}"></label><label class="field full">Номера вручную<textarea id="issueManual" placeholder="По одному номеру или внутреннему ID в строке"></textarea><button type="button" class="button secondary small" id="confirmManual">Подтвердить номера</button></label></div><div class="scan-line" id="seriesHint">Выберите серию, чтобы увидеть её баллоны.</div><div class="chips" id="seriesCylinderList"></div><div class="scan-line" id="volumeSummary">Баллоны ещё не выбраны.</div><div class="form-actions"><button type="button" class="button secondary" id="previewProtocol">Предпросмотр</button><button class="button">Оформить выдачу</button></div></form><div class="card panel" style="margin-top:20px"><div class="panel-head"><h2>История выдач</h2><small>Удаление недоступно: запись можно только аннулировать.</small></div><div class="table-wrap"><table class="table"><thead><tr><th>Дата</th><th>Организация</th><th>Накладная</th><th>Серия</th><th>Статус</th><th></th></tr></thead><tbody>${state.issues.map((i,n)=>`<tr><td>${date(i.date)}</td><td>${i.org}</td><td>№${i.invoice}</td><td>${i.batch}</td><td>${status(i.cancelled?'Аннулирован':'Действует')}</td><td><button class="button secondary small" data-edit-issue="${n}">Изменить</button>${i.cancelled?'':` <button class="button danger small" data-cancel-issue="${n}">Аннулировать</button>`}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Выдач пока нет</td></tr>'}</tbody></table></div></div>`;$('#issueBatch').onchange=syncBatch;$('#organizationSelect').onchange=e=>{if(e.target.value)$('#organizationInput').value=e.target.value};$('#confirmManual').onclick=confirmManualCylinders;$('#issueForm').onsubmit=e=>finishIssue(e,false);$('#previewProtocol').onclick=()=>finishIssue(null,true);document.querySelectorAll('[data-cancel-issue]').forEach(b=>b.onclick=()=>cancelIssue(+b.dataset.cancelIssue));document.querySelectorAll('[data-edit-issue]').forEach(b=>b.onclick=()=>editIssue(+b.dataset.editIssue))}
function selectedBatch(){return state.batches.find(b=>b.number===$('#issueBatch')?.value)}
function batchAvailable(b){return (b?.cylinders||[]).map(u=>cyl(u)).filter(c=>c&&['На складе','Возвращён'].includes(c.status))}
function syncBatch(){let b=selectedBatch();if(!b)return;$('#issueProduction').value=b.produced||'';$('#expiry').value=b.expiry||plus18(b.produced);$('#issuePermission').value=b.permissionDate||'';let items=batchAvailable(b);$('#seriesHint').textContent=items.length?`Баллоны серии ${b.number}: выберите нужные.`:'В этой серии нет доступных баллонов.';$('#seriesCylinderList').innerHTML=items.map(c=>`<label class="chip"><input type="checkbox" name="cylinder" value="${c.uid}"> ${c.id} · ${c.volume||b.volume||'объём не указан'} л <small>${c.uid}</small></label>`).join('');$('#seriesCylinderList').querySelectorAll('input').forEach(x=>x.onchange=updateVolumeSummary);updateVolumeSummary()}
function seriesManualMatch(text){let items=batchAvailable(selectedBatch()),values=(text||'').split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean),found=[],miss=[];values.forEach(v=>{let c=items.find(c=>c.uid===v||c.id===v);c&&!found.includes(c.uid)?found.push(c.uid):miss.push(v)});return{found,miss}}
function confirmManualCylinders(){let r=seriesManualMatch($('#issueManual').value);if(r.miss.length){toast(`Нет в выбранной серии или недоступны: ${r.miss.join(', ')}`);return}if(!r.found.length){toast('Введите хотя бы один номер баллона');return}r.found.forEach(u=>{let box=$(`#seriesCylinderList input[value="${u}"]`);if(box)box.checked=true});updateVolumeSummary();toast('Баллоны по введённым номерам отмечены')}
function updateVolumeSummary(){let b=selectedBatch(),items=[...document.querySelectorAll('#seriesCylinderList input:checked')].map(x=>cyl(x.value)).filter(Boolean);$('#volumeSummary').innerHTML=items.length?`К выдаче: ${items.map(c=>`<strong>${c.id}</strong> — ${c.volume||b?.volume||'объём не указан'} л`).join(' · ')}`:'Баллоны ещё не выбраны.'}
// The primary issue form now owns additional-series behaviour, so legacy decoration is disabled.
function decorateIssueForm(){}
function issueData(){let f=$('#issueForm');if(!f.reportValidity())return null;let fd=new FormData(f),x=Object.fromEntries(fd),manual=seriesManualMatch($('#issueManual').value);if(manual.miss.length){toast(`Нет в выбранной серии или недоступны: ${manual.miss.join(', ')}`);return null}manual.found.forEach(u=>{let box=$(`#seriesCylinderList input[value="${u}"]`);if(box)box.checked=true});x.cylinders=[...new Set([...fd.getAll('cylinder'),...manual.found])];if(!x.cylinders.length){toast('Выберите баллоны или подтвердите введённые номера');return null}x.expiry=$('#expiry').value;if(x.expiry&&x.date>x.expiry){toast('Срок годности серии истёк: выдача невозможна');return null}x.series=[x.batch];return x}
